// Totals per category from the rows of the sheet
const totals = {};
let sum = 0;
for (const entry of context.items || []) {
  const row = entry && typeof entry === "object" && "json" in entry ? entry.json : entry;
  const amount = Number(row.amount || 0);
  const category = String(row.category || "other");
  totals[category] = (totals[category] || 0) + amount;
  sum += amount;
}
return {
  lines: Object.keys(totals).sort().map((name) => "- " + name + ": " + totals[name].toFixed(2)).join("\n"),
  total: sum.toFixed(2),
  rows: (context.items || []).length,
};

